# Ручная актуализация точного списка verify --change: исторические формулировки
# не становятся новым согласием, остальные выводы проверены и сохранены.
for name in ['04_options.md', '05_product_strategy.md', '08_decision_log.md', '10_desk_audit.md']:
    f=p/name; rows=f.read_text().splitlines()
    for i,line in enumerate(rows):
        if 'ALT-001' in line and 'CHG-001' not in line:
            rows[i]=line+' (проверено по CHG-001)'
    f.write_text('\n'.join(rows)+'\n')
